    wire stream_wr_128b_b_rarb_vld = (stream_wr_128b_b_rgnt_ddr && stream_wr_128b_b_rarb_req[0]) || (stream_wr_128b_b_rgnt_crc_snk && stream_wr_128b_b_rarb_req[1]) || (stream_wr_128b_b_rgnt_subtractive && stream_wr_128b_b_rarb_req[2]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            stream_wr_128b_b_rarb_lock   <= '0;
            stream_wr_128b_b_rarb_rr     <= '0;
            stream_wr_128b_b_rarb_locked <= 1'b0;
        end else if (stream_wr_128b_b_rarb_vld && stream_wr_128b_bready) begin
            stream_wr_128b_b_rarb_locked <= 1'b0;
            stream_wr_128b_b_rarb_rr <= (stream_wr_128b_b_rarb_gnt == 2'd2) ? 2'd0 : stream_wr_128b_b_rarb_gnt + 1'b1;
        end else if (stream_wr_128b_b_rarb_vld) begin
            stream_wr_128b_b_rarb_lock   <= stream_wr_128b_b_rarb_gnt;       // offered, not taken: hold
            stream_wr_128b_b_rarb_locked <= 1'b1;
        end
    )

    // ---- B response arbiter, master inj_wr 128b: round-robin, lock until taken ----
    logic [1:0] inj_wr_128b_b_rarb_req;
    assign inj_wr_128b_b_rarb_req = {((subtractive_axi_bid_bridge_id == 3) && subtractive_axi_bid_valid) && subtractive_axi_bvalid, ((ddr_axi_bid_bridge_id == 3) && ddr_axi_bid_valid) && ddr_axi_bvalid};
    logic [0:0] inj_wr_128b_b_rarb_lock, inj_wr_128b_b_rarb_rr;
    logic inj_wr_128b_b_rarb_locked;
    wire [0:0] inj_wr_128b_b_rarb_pick = (inj_wr_128b_b_rarb_rr == 1'd0) ? (inj_wr_128b_b_rarb_req[0] ? 1'd0 : 1'd1) : 
        inj_wr_128b_b_rarb_req[1] ? 1'd1 : 1'd0;
    wire [0:0] inj_wr_128b_b_rarb_gnt = inj_wr_128b_b_rarb_locked ? inj_wr_128b_b_rarb_lock : inj_wr_128b_b_rarb_pick;
    wire inj_wr_128b_b_rarb_gnt_valid = inj_wr_128b_b_rarb_locked || (|inj_wr_128b_b_rarb_req);
    wire inj_wr_128b_b_rgnt_ddr = inj_wr_128b_b_rarb_gnt_valid && (inj_wr_128b_b_rarb_gnt == 1'd0);
    wire inj_wr_128b_b_rgnt_subtractive = inj_wr_128b_b_rarb_gnt_valid && (inj_wr_128b_b_rarb_gnt == 1'd1);
    wire inj_wr_128b_b_rarb_vld = (inj_wr_128b_b_rgnt_ddr && inj_wr_128b_b_rarb_req[0]) || (inj_wr_128b_b_rgnt_subtractive && inj_wr_128b_b_rarb_req[1]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            inj_wr_128b_b_rarb_lock   <= '0;
            inj_wr_128b_b_rarb_rr     <= '0;
            inj_wr_128b_b_rarb_locked <= 1'b0;
        end else if (inj_wr_128b_b_rarb_vld && inj_wr_128b_bready) begin
            inj_wr_128b_b_rarb_locked <= 1'b0;
            inj_wr_128b_b_rarb_rr <= (inj_wr_128b_b_rarb_gnt == 1'd1) ? 1'd0 : inj_wr_128b_b_rarb_gnt + 1'b1;
        end else if (inj_wr_128b_b_rarb_vld) begin
            inj_wr_128b_b_rarb_lock   <= inj_wr_128b_b_rarb_gnt;       // offered, not taken: hold
            inj_wr_128b_b_rarb_locked <= 1'b1;
        end
    )

    // ================================================================
    // Slave 0: ddr (128b)
    // ================================================================
    // Multi-master (3 masters) → ddr
    //   - stream_rd (rd)
    //   - stream_wr (wr)
    //   - inj_wr (wr)

    wire stream_rd_128b_ar_to_ddr = (stream_rd_128b_ar.addr <= 32'h3fffffff);
    wire stream_wr_128b_aw_to_ddr = (stream_wr_128b_aw.addr <= 32'h3fffffff);
    wire inj_wr_128b_aw_to_ddr = (inj_wr_128b_aw.addr <= 32'h3fffffff);

    // ---- AW arbiter for ddr: round-robin, lock until handshake ----
    logic [1:0] ddr_aw_arb_req;
    assign ddr_aw_arb_req = {inj_wr_128b_aw_to_ddr && inj_wr_128b_awvalid, stream_wr_128b_aw_to_ddr && stream_wr_128b_awvalid};
    logic [0:0] ddr_aw_arb_lock, ddr_aw_arb_rr;
    logic ddr_aw_arb_locked;
    wire [0:0] ddr_aw_arb_pick = (ddr_aw_arb_rr == 1'd0) ? (ddr_aw_arb_req[0] ? 1'd0 : 1'd1) : 
        ddr_aw_arb_req[1] ? 1'd1 : 1'd0;
    wire ddr_aw_arb_gnt_valid = ddr_aw_arb_locked || (|ddr_aw_arb_req);
    wire [0:0] ddr_aw_arb_gnt = ddr_aw_arb_locked ? ddr_aw_arb_lock : ddr_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_aw_arb_lock   <= '0;
            ddr_aw_arb_rr     <= '0;
            ddr_aw_arb_locked <= 1'b0;
        end else begin
            if (ddr_axi_awvalid && ddr_axi_awready) begin
                ddr_aw_arb_locked <= 1'b0;
                ddr_aw_arb_rr <= (ddr_aw_arb_gnt == 1'd1) ? 1'd0 : ddr_aw_arb_gnt + 1'b1;
            end else if (ddr_axi_awvalid) begin
                ddr_aw_arb_lock   <= ddr_aw_arb_gnt;
                ddr_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire stream_wr_128b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd0) && ddr_aw_arb_req[0];
    wire inj_wr_128b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd1) && ddr_aw_arb_req[1];

    // AW channel (arbitrated mux across writing masters)
    assign ddr_axi_awid = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.id : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.id : '0);
    assign ddr_axi_awaddr = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.addr : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.addr : '0);
    assign ddr_axi_awlen = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.len : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.len : '0);
    assign ddr_axi_awsize = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.size : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.size : '0);
    assign ddr_axi_awburst = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.burst : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.burst : '0);
    assign ddr_axi_awlock = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.lock : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.lock : '0);
    assign ddr_axi_awcache = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.cache : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.cache : '0);
    assign ddr_axi_awprot = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.prot : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.prot : '0);
    assign ddr_axi_awqos = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.qos : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.qos : '0);
    assign ddr_axi_awregion = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.region : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.region : '0);
    assign ddr_axi_awuser = (stream_wr_128b_aw_gnt_ddr ? stream_wr_128b_aw.user : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_128b_aw.user : '0);
    assign ddr_axi_awvalid = stream_wr_128b_aw_gnt_ddr || inj_wr_128b_aw_gnt_ddr;

    // W owner FIFO: slave-side AW accept order owns the W channel
    logic [0:0] ddr_wowner_mem [16];
    logic [4:0] ddr_wowner_wptr, ddr_wowner_rptr;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_wowner_wptr <= '0;
            ddr_wowner_rptr <= '0;
        end else begin
            if (ddr_axi_awvalid && ddr_axi_awready) begin
                ddr_wowner_mem[ddr_wowner_wptr[3:0]] <= ddr_aw_arb_gnt;
                ddr_wowner_wptr <= ddr_wowner_wptr + 1'b1;
            end
            if (ddr_axi_wvalid && ddr_axi_wready && ddr_axi_wlast) begin
                ddr_wowner_rptr <= ddr_wowner_rptr + 1'b1;
            end
        end
    )
    wire ddr_wowner_valid = (ddr_wowner_wptr != ddr_wowner_rptr);
    wire [0:0] ddr_wowner_head = ddr_wowner_mem[ddr_wowner_rptr[3:0]];
    assign stream_wr_128b_w_sel_ddr = ddr_wowner_valid && (ddr_wowner_head == 1'd0) && stream_wr_128b_w_to_ddr;
    assign inj_wr_128b_w_sel_ddr = ddr_wowner_valid && (ddr_wowner_head == 1'd1) && inj_wr_128b_w_to_ddr;

    // W channel (owner-gated mux across writing masters)
    assign ddr_axi_wdata = ((stream_wr_128b_w_sel_ddr && stream_wr_128b_wvalid) ? stream_wr_128b_w.data : '0) |
        ((inj_wr_128b_w_sel_ddr && inj_wr_128b_wvalid) ? inj_wr_128b_w.data : '0);
    assign ddr_axi_wstrb = ((stream_wr_128b_w_sel_ddr && stream_wr_128b_wvalid) ? stream_wr_128b_w.strb : '0) |
        ((inj_wr_128b_w_sel_ddr && inj_wr_128b_wvalid) ? inj_wr_128b_w.strb : '0);
    assign ddr_axi_wlast = ((stream_wr_128b_w_sel_ddr && stream_wr_128b_wvalid) ? stream_wr_128b_w.last : '0) |
        ((inj_wr_128b_w_sel_ddr && inj_wr_128b_wvalid) ? inj_wr_128b_w.last : '0);
    assign ddr_axi_wuser = ((stream_wr_128b_w_sel_ddr && stream_wr_128b_wvalid) ? stream_wr_128b_w.user : '0) |
        ((inj_wr_128b_w_sel_ddr && inj_wr_128b_wvalid) ? inj_wr_128b_w.user : '0);
    assign ddr_axi_wvalid = (stream_wr_128b_w_sel_ddr && stream_wr_128b_wvalid) || (inj_wr_128b_w_sel_ddr && inj_wr_128b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign ddr_axi_bready = (stream_wr_128b_b_rgnt_ddr ? stream_wr_128b_bready : '0) |
        (inj_wr_128b_b_rgnt_ddr ? inj_wr_128b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign ddr_axi_bridge_id_aw = (stream_wr_128b_aw_gnt_ddr ? stream_wr_bridge_id_aw : '0) |
        (inj_wr_128b_aw_gnt_ddr ? inj_wr_bridge_id_aw : '0);

    // ---- AR arbiter for ddr: round-robin, lock until handshake ----
    logic [0:0] ddr_ar_arb_req;
    assign ddr_ar_arb_req = {stream_rd_128b_ar_to_ddr && stream_rd_128b_arvalid};
    logic [0:0] ddr_ar_arb_lock, ddr_ar_arb_rr;
    logic ddr_ar_arb_locked;
    wire [0:0] ddr_ar_arb_pick = 1'd0;
    wire ddr_ar_arb_gnt_valid = ddr_ar_arb_locked || (|ddr_ar_arb_req);
    wire [0:0] ddr_ar_arb_gnt = ddr_ar_arb_locked ? ddr_ar_arb_lock : ddr_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_ar_arb_lock   <= '0;
            ddr_ar_arb_rr     <= '0;
            ddr_ar_arb_locked <= 1'b0;
        end else begin
            if (ddr_axi_arvalid && ddr_axi_arready) begin
                ddr_ar_arb_locked <= 1'b0;
                ddr_ar_arb_rr <= (ddr_ar_arb_gnt == 1'd0) ? 1'd0 : ddr_ar_arb_gnt + 1'b1;
            end else if (ddr_axi_arvalid) begin
                ddr_ar_arb_lock   <= ddr_ar_arb_gnt;
                ddr_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire stream_rd_128b_ar_gnt_ddr = ddr_ar_arb_gnt_valid && (ddr_ar_arb_gnt == 1'd0) && ddr_ar_arb_req[0];

    // AR channel (arbitrated mux across reading masters)
    assign ddr_axi_arid = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.id : '0);
    assign ddr_axi_araddr = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.addr : '0);
    assign ddr_axi_arlen = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.len : '0);
    assign ddr_axi_arsize = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.size : '0);
    assign ddr_axi_arburst = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.burst : '0);
    assign ddr_axi_arlock = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.lock : '0);
    assign ddr_axi_arcache = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.cache : '0);
    assign ddr_axi_arprot = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.prot : '0);
    assign ddr_axi_arqos = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.qos : '0);
    assign ddr_axi_arregion = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.region : '0);
    assign ddr_axi_aruser = (stream_rd_128b_ar_gnt_ddr ? stream_rd_128b_ar.user : '0);
    assign ddr_axi_arvalid = stream_rd_128b_ar_gnt_ddr;

    // Rready (slave -> the master whose response arbiter granted it)
    assign ddr_axi_rready = (stream_rd_128b_r_rgnt_ddr ? stream_rd_128b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign ddr_axi_bridge_id_ar = (stream_rd_128b_ar_gnt_ddr ? stream_rd_bridge_id_ar : '0);


    // ================================================================
    // Slave 1: desc_ram (128b)
    // ================================================================
    // Single master: stream_desc → desc_ram
    // Master width: 128b, Slave width: 128b
    // Using 128b path from adapter

    // AR channel (gated by address re-decode -- see _addr_decode_expr)
    wire stream_desc_128b_ar_to_desc_ram = ((stream_desc_128b_ar.addr >= 32'h80000000) && (stream_desc_128b_ar.addr <= 32'h8000ffff));
    wire stream_desc_128b_ar_gnt_desc_ram = stream_desc_128b_ar_to_desc_ram;
    assign desc_ram_axi_arid     = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.id : '0;
    assign desc_ram_axi_araddr   = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.addr : '0;
    assign desc_ram_axi_arlen    = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.len : '0;
    assign desc_ram_axi_arsize   = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.size : '0;
    assign desc_ram_axi_arburst  = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.burst : '0;
    assign desc_ram_axi_arlock   = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.lock : '0;
    assign desc_ram_axi_arcache  = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.cache : '0;
    assign desc_ram_axi_arprot   = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.prot : '0;
    assign desc_ram_axi_arqos    = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.qos : '0;
    assign desc_ram_axi_arregion = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.region : '0;
    assign desc_ram_axi_aruser   = stream_desc_128b_ar_to_desc_ram ? stream_desc_128b_ar.user : '0;
    assign desc_ram_axi_arvalid  = stream_desc_128b_ar_to_desc_ram && stream_desc_128b_arvalid;

    // Rready (master → slave) — gated on rid_valid so the path stays
    // open through the entire R handshake, not just the AR phase.
    assign desc_ram_axi_rready = stream_desc_128b_r_rgnt_desc_ram ? stream_desc_128b_rready : '0;

    // Bridge ID (master → slave)
    assign desc_ram_axi_bridge_id_ar = stream_desc_128b_ar_to_desc_ram ? stream_desc_bridge_id_ar : '0;


    // ================================================================
    // Slave 2: lfsr_src (128b)
    // ================================================================
    // Single master: stream_rd → lfsr_src
    // Master width: 128b, Slave width: 128b
    // Using 128b path from adapter

    // AR channel (gated by address re-decode -- see _addr_decode_expr)
    wire stream_rd_128b_ar_to_lfsr_src = ((stream_rd_128b_ar.addr >= 32'h90000000) && (stream_rd_128b_ar.addr <= 32'h9fffffff));
    wire stream_rd_128b_ar_gnt_lfsr_src = stream_rd_128b_ar_to_lfsr_src;
    assign lfsr_src_axi_arid     = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.id : '0;
    assign lfsr_src_axi_araddr   = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.addr : '0;
    assign lfsr_src_axi_arlen    = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.len : '0;
    assign lfsr_src_axi_arsize   = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.size : '0;
    assign lfsr_src_axi_arburst  = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.burst : '0;
    assign lfsr_src_axi_arlock   = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.lock : '0;
    assign lfsr_src_axi_arcache  = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.cache : '0;
    assign lfsr_src_axi_arprot   = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.prot : '0;
    assign lfsr_src_axi_arqos    = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.qos : '0;
    assign lfsr_src_axi_arregion = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.region : '0;
    assign lfsr_src_axi_aruser   = stream_rd_128b_ar_to_lfsr_src ? stream_rd_128b_ar.user : '0;
    assign lfsr_src_axi_arvalid  = stream_rd_128b_ar_to_lfsr_src && stream_rd_128b_arvalid;

    // Rready (master → slave) — gated on rid_valid so the path stays
    // open through the entire R handshake, not just the AR phase.
    assign lfsr_src_axi_rready = stream_rd_128b_r_rgnt_lfsr_src ? stream_rd_128b_rready : '0;

    // Bridge ID (master → slave)
    assign lfsr_src_axi_bridge_id_ar = stream_rd_128b_ar_to_lfsr_src ? stream_rd_bridge_id_ar : '0;


    // ================================================================
    // Slave 3: crc_snk (128b)
    // ================================================================
    // Single master: stream_wr → crc_snk
    // Master width: 128b, Slave width: 128b
    // Using 128b path from adapter

    // AW channel (gated by address re-decode -- see _addr_decode_expr)
    wire stream_wr_128b_aw_to_crc_snk = ((stream_wr_128b_aw.addr >= 32'ha0000000) && (stream_wr_128b_aw.addr <= 32'hafffffff));
    wire stream_wr_128b_aw_gnt_crc_snk = stream_wr_128b_aw_to_crc_snk;
    assign crc_snk_axi_awid     = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.id : '0;
    assign crc_snk_axi_awaddr   = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.addr : '0;
    assign crc_snk_axi_awlen    = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.len : '0;
    assign crc_snk_axi_awsize   = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.size : '0;
    assign crc_snk_axi_awburst  = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.burst : '0;
    assign crc_snk_axi_awlock   = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.lock : '0;
    assign crc_snk_axi_awcache  = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.cache : '0;
    assign crc_snk_axi_awprot   = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.prot : '0;
    assign crc_snk_axi_awqos    = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.qos : '0;
    assign crc_snk_axi_awregion = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.region : '0;
    assign crc_snk_axi_awuser   = stream_wr_128b_aw_to_crc_snk ? stream_wr_128b_aw.user : '0;
    assign crc_snk_axi_awvalid  = stream_wr_128b_aw_to_crc_snk && stream_wr_128b_awvalid;

    assign stream_wr_128b_w_sel_crc_snk = stream_wr_128b_w_to_crc_snk;

    // W channel (gated by the W destination FIFO head)
    assign crc_snk_axi_wdata  = stream_wr_128b_w_to_crc_snk ? stream_wr_128b_w.data : '0;
    assign crc_snk_axi_wstrb  = stream_wr_128b_w_to_crc_snk ? stream_wr_128b_w.strb : '0;
    assign crc_snk_axi_wlast  = stream_wr_128b_w_to_crc_snk ? stream_wr_128b_w.last : '0;
    assign crc_snk_axi_wuser  = stream_wr_128b_w_to_crc_snk ? stream_wr_128b_w.user : '0;
    assign crc_snk_axi_wvalid = stream_wr_128b_w_to_crc_snk && stream_wr_128b_wvalid;

    // Bready (master → slave) — gated on bid_valid so the path stays
    // open through the entire B handshake, not just the AW phase.
    assign crc_snk_axi_bready = stream_wr_128b_b_rgnt_crc_snk ? stream_wr_128b_bready : '0;

    // Bridge ID (master → slave)
    assign crc_snk_axi_bridge_id_aw = stream_wr_128b_aw_to_crc_snk ? stream_wr_bridge_id_aw : '0;


    // ================================================================
    // Slave 4: subtractive (128b)
    // ================================================================
    // Multi-master (4 masters) → subtractive
    //   - stream_desc (rd)
    //   - stream_rd (rd)
    //   - stream_wr (wr)
    //   - inj_wr (wr)

    wire stream_desc_128b_ar_to_subtractive = !((((stream_desc_128b_ar.addr >= 32'h80000000) && (stream_desc_128b_ar.addr <= 32'h8000ffff))));
    wire stream_rd_128b_ar_to_subtractive = !(((stream_rd_128b_ar.addr <= 32'h3fffffff)) || (((stream_rd_128b_ar.addr >= 32'h90000000) && (stream_rd_128b_ar.addr <= 32'h9fffffff))));
    wire stream_wr_128b_aw_to_subtractive = !(((stream_wr_128b_aw.addr <= 32'h3fffffff)) || (((stream_wr_128b_aw.addr >= 32'ha0000000) && (stream_wr_128b_aw.addr <= 32'hafffffff))));
    wire inj_wr_128b_aw_to_subtractive = !(((inj_wr_128b_aw.addr <= 32'h3fffffff)));

    // ---- AW arbiter for subtractive: round-robin, lock until handshake ----
    logic [1:0] subtractive_aw_arb_req;
    assign subtractive_aw_arb_req = {inj_wr_128b_aw_to_subtractive && inj_wr_128b_awvalid, stream_wr_128b_aw_to_subtractive && stream_wr_128b_awvalid};
    logic [0:0] subtractive_aw_arb_lock, subtractive_aw_arb_rr;
    logic subtractive_aw_arb_locked;
    wire [0:0] subtractive_aw_arb_pick = (subtractive_aw_arb_rr == 1'd0) ? (subtractive_aw_arb_req[0] ? 1'd0 : 1'd1) : 
        subtractive_aw_arb_req[1] ? 1'd1 : 1'd0;
    wire subtractive_aw_arb_gnt_valid = subtractive_aw_arb_locked || (|subtractive_aw_arb_req);
    wire [0:0] subtractive_aw_arb_gnt = subtractive_aw_arb_locked ? subtractive_aw_arb_lock : subtractive_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_aw_arb_lock   <= '0;
            subtractive_aw_arb_rr     <= '0;
            subtractive_aw_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_awvalid && subtractive_axi_awready) begin
                subtractive_aw_arb_locked <= 1'b0;
                subtractive_aw_arb_rr <= (subtractive_aw_arb_gnt == 1'd1) ? 1'd0 : subtractive_aw_arb_gnt + 1'b1;
            end else if (subtractive_axi_awvalid) begin
                subtractive_aw_arb_lock   <= subtractive_aw_arb_gnt;
                subtractive_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire stream_wr_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 1'd0) && subtractive_aw_arb_req[0];
    wire inj_wr_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 1'd1) && subtractive_aw_arb_req[1];

    // AW channel (arbitrated mux across writing masters)
    assign subtractive_axi_awid = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.id : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.id : '0);
    assign subtractive_axi_awaddr = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.addr : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.addr : '0);
    assign subtractive_axi_awlen = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.len : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.len : '0);
    assign subtractive_axi_awsize = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.size : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.size : '0);
    assign subtractive_axi_awburst = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.burst : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.burst : '0);
    assign subtractive_axi_awlock = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.lock : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.lock : '0);
    assign subtractive_axi_awcache = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.cache : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.cache : '0);
    assign subtractive_axi_awprot = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.prot : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.prot : '0);
    assign subtractive_axi_awqos = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.qos : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.qos : '0);
    assign subtractive_axi_awregion = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.region : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.region : '0);
    assign subtractive_axi_awuser = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_128b_aw.user : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_128b_aw.user : '0);
    assign subtractive_axi_awvalid = stream_wr_128b_aw_gnt_subtractive || inj_wr_128b_aw_gnt_subtractive;

    // W owner FIFO: slave-side AW accept order owns the W channel
    logic [0:0] subtractive_wowner_mem [16];
    logic [4:0] subtractive_wowner_wptr, subtractive_wowner_rptr;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_wowner_wptr <= '0;
            subtractive_wowner_rptr <= '0;
        end else begin
            if (subtractive_axi_awvalid && subtractive_axi_awready) begin
                subtractive_wowner_mem[subtractive_wowner_wptr[3:0]] <= subtractive_aw_arb_gnt;
                subtractive_wowner_wptr <= subtractive_wowner_wptr + 1'b1;
            end
            if (subtractive_axi_wvalid && subtractive_axi_wready && subtractive_axi_wlast) begin
                subtractive_wowner_rptr <= subtractive_wowner_rptr + 1'b1;
            end
        end
    )
    wire subtractive_wowner_valid = (subtractive_wowner_wptr != subtractive_wowner_rptr);
    wire [0:0] subtractive_wowner_head = subtractive_wowner_mem[subtractive_wowner_rptr[3:0]];
    assign stream_wr_128b_w_sel_subtractive = subtractive_wowner_valid && (subtractive_wowner_head == 1'd0) && stream_wr_128b_w_to_subtractive;
    assign inj_wr_128b_w_sel_subtractive = subtractive_wowner_valid && (subtractive_wowner_head == 1'd1) && inj_wr_128b_w_to_subtractive;

    // W channel (owner-gated mux across writing masters)
    assign subtractive_axi_wdata = ((stream_wr_128b_w_sel_subtractive && stream_wr_128b_wvalid) ? stream_wr_128b_w.data : '0) |
        ((inj_wr_128b_w_sel_subtractive && inj_wr_128b_wvalid) ? inj_wr_128b_w.data : '0);
    assign subtractive_axi_wstrb = ((stream_wr_128b_w_sel_subtractive && stream_wr_128b_wvalid) ? stream_wr_128b_w.strb : '0) |
        ((inj_wr_128b_w_sel_subtractive && inj_wr_128b_wvalid) ? inj_wr_128b_w.strb : '0);
    assign subtractive_axi_wlast = ((stream_wr_128b_w_sel_subtractive && stream_wr_128b_wvalid) ? stream_wr_128b_w.last : '0) |
        ((inj_wr_128b_w_sel_subtractive && inj_wr_128b_wvalid) ? inj_wr_128b_w.last : '0);
    assign subtractive_axi_wuser = ((stream_wr_128b_w_sel_subtractive && stream_wr_128b_wvalid) ? stream_wr_128b_w.user : '0) |
        ((inj_wr_128b_w_sel_subtractive && inj_wr_128b_wvalid) ? inj_wr_128b_w.user : '0);
    assign subtractive_axi_wvalid = (stream_wr_128b_w_sel_subtractive && stream_wr_128b_wvalid) || (inj_wr_128b_w_sel_subtractive && inj_wr_128b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_bready = (stream_wr_128b_b_rgnt_subtractive ? stream_wr_128b_bready : '0) |
        (inj_wr_128b_b_rgnt_subtractive ? inj_wr_128b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign subtractive_axi_bridge_id_aw = (stream_wr_128b_aw_gnt_subtractive ? stream_wr_bridge_id_aw : '0) |
        (inj_wr_128b_aw_gnt_subtractive ? inj_wr_bridge_id_aw : '0);

    // ---- AR arbiter for subtractive: round-robin, lock until handshake ----
    logic [1:0] subtractive_ar_arb_req;
    assign subtractive_ar_arb_req = {stream_rd_128b_ar_to_subtractive && stream_rd_128b_arvalid, stream_desc_128b_ar_to_subtractive && stream_desc_128b_arvalid};
    logic [0:0] subtractive_ar_arb_lock, subtractive_ar_arb_rr;
    logic subtractive_ar_arb_locked;
    wire [0:0] subtractive_ar_arb_pick = (subtractive_ar_arb_rr == 1'd0) ? (subtractive_ar_arb_req[0] ? 1'd0 : 1'd1) : 
        subtractive_ar_arb_req[1] ? 1'd1 : 1'd0;
    wire subtractive_ar_arb_gnt_valid = subtractive_ar_arb_locked || (|subtractive_ar_arb_req);
    wire [0:0] subtractive_ar_arb_gnt = subtractive_ar_arb_locked ? subtractive_ar_arb_lock : subtractive_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_ar_arb_lock   <= '0;
            subtractive_ar_arb_rr     <= '0;
            subtractive_ar_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_arvalid && subtractive_axi_arready) begin
                subtractive_ar_arb_locked <= 1'b0;
                subtractive_ar_arb_rr <= (subtractive_ar_arb_gnt == 1'd1) ? 1'd0 : subtractive_ar_arb_gnt + 1'b1;
            end else if (subtractive_axi_arvalid) begin
                subtractive_ar_arb_lock   <= subtractive_ar_arb_gnt;
                subtractive_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire stream_desc_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd0) && subtractive_ar_arb_req[0];
    wire stream_rd_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd1) && subtractive_ar_arb_req[1];

    // AR channel (arbitrated mux across reading masters)
    assign subtractive_axi_arid = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.id : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.id : '0);
    assign subtractive_axi_araddr = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.addr : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.addr : '0);
    assign subtractive_axi_arlen = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.len : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.len : '0);
    assign subtractive_axi_arsize = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.size : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.size : '0);
    assign subtractive_axi_arburst = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.burst : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.burst : '0);
    assign subtractive_axi_arlock = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.lock : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.lock : '0);
    assign subtractive_axi_arcache = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.cache : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.cache : '0);
    assign subtractive_axi_arprot = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.prot : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.prot : '0);
    assign subtractive_axi_arqos = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.qos : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.qos : '0);
    assign subtractive_axi_arregion = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.region : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.region : '0);
    assign subtractive_axi_aruser = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_128b_ar.user : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_128b_ar.user : '0);
    assign subtractive_axi_arvalid = stream_desc_128b_ar_gnt_subtractive || stream_rd_128b_ar_gnt_subtractive;

    // Rready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_rready = (stream_desc_128b_r_rgnt_subtractive ? stream_desc_128b_rready : '0) |
        (stream_rd_128b_r_rgnt_subtractive ? stream_rd_128b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign subtractive_axi_bridge_id_ar = (stream_desc_128b_ar_gnt_subtractive ? stream_desc_bridge_id_ar : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? stream_rd_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // stream_wr 128b path -> ddr, crc_snk, subtractive
    logic [1:0] stream_wr_128b_wdest_mem [16];
    logic [4:0] stream_wr_128b_wdest_wptr, stream_wr_128b_wdest_rptr;
    wire [1:0] stream_wr_128b_wdest_enc = stream_wr_128b_aw_to_crc_snk ? 2'd1 : stream_wr_128b_aw_to_subtractive ? 2'd2 : 2'd0;
    wire stream_wr_128b_wdest_push = stream_wr_128b_awvalid && stream_wr_128b_awready;
    wire stream_wr_128b_wdest_pop  = stream_wr_128b_wvalid && stream_wr_128b_wready && stream_wr_128b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            stream_wr_128b_wdest_wptr <= '0;
            stream_wr_128b_wdest_rptr <= '0;
        end else begin
            if (stream_wr_128b_wdest_push) begin
                stream_wr_128b_wdest_mem[stream_wr_128b_wdest_wptr[3:0]] <= stream_wr_128b_wdest_enc;
                stream_wr_128b_wdest_wptr <= stream_wr_128b_wdest_wptr + 1'b1;
            end
            if (stream_wr_128b_wdest_pop) begin
                stream_wr_128b_wdest_rptr <= stream_wr_128b_wdest_rptr + 1'b1;
            end
        end
    )
    wire stream_wr_128b_wdest_valid = (stream_wr_128b_wdest_wptr != stream_wr_128b_wdest_rptr);
    wire [1:0] stream_wr_128b_wdest_head = stream_wr_128b_wdest_mem[stream_wr_128b_wdest_rptr[3:0]];
    assign stream_wr_128b_w_to_ddr = stream_wr_128b_wdest_valid && (stream_wr_128b_wdest_head == 2'd0);
    assign stream_wr_128b_w_to_crc_snk = stream_wr_128b_wdest_valid && (stream_wr_128b_wdest_head == 2'd1);
    assign stream_wr_128b_w_to_subtractive = stream_wr_128b_wdest_valid && (stream_wr_128b_wdest_head == 2'd2);

    // inj_wr 128b path -> ddr, subtractive
    logic [0:0] inj_wr_128b_wdest_mem [16];
    logic [4:0] inj_wr_128b_wdest_wptr, inj_wr_128b_wdest_rptr;
    wire [0:0] inj_wr_128b_wdest_enc = inj_wr_128b_aw_to_subtractive ? 1'd1 : 1'd0;
    wire inj_wr_128b_wdest_push = inj_wr_128b_awvalid && inj_wr_128b_awready;
    wire inj_wr_128b_wdest_pop  = inj_wr_128b_wvalid && inj_wr_128b_wready && inj_wr_128b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            inj_wr_128b_wdest_wptr <= '0;
            inj_wr_128b_wdest_rptr <= '0;
        end else begin
            if (inj_wr_128b_wdest_push) begin
                inj_wr_128b_wdest_mem[inj_wr_128b_wdest_wptr[3:0]] <= inj_wr_128b_wdest_enc;
                inj_wr_128b_wdest_wptr <= inj_wr_128b_wdest_wptr + 1'b1;
            end
            if (inj_wr_128b_wdest_pop) begin
                inj_wr_128b_wdest_rptr <= inj_wr_128b_wdest_rptr + 1'b1;
            end
        end
    )
    wire inj_wr_128b_wdest_valid = (inj_wr_128b_wdest_wptr != inj_wr_128b_wdest_rptr);
    wire [0:0] inj_wr_128b_wdest_head = inj_wr_128b_wdest_mem[inj_wr_128b_wdest_rptr[3:0]];
    assign inj_wr_128b_w_to_ddr = inj_wr_128b_wdest_valid && (inj_wr_128b_wdest_head == 1'd0);
    assign inj_wr_128b_w_to_subtractive = inj_wr_128b_wdest_valid && (inj_wr_128b_wdest_head == 1'd1);

    // ================================================================
    // Response MUXes (OR together all slave responses)
    // ================================================================

    // Master: stream_desc, Width path: 128b
    assign stream_desc_128b_arready = 
        (stream_desc_128b_ar_gnt_desc_ram ? desc_ram_axi_arready : '0) |
        (stream_desc_128b_ar_gnt_subtractive ? subtractive_axi_arready : '0);

    assign stream_desc_128b_r.id = 
        (stream_desc_128b_r_rgnt_desc_ram ? desc_ram_axi_rid : '0) |
        (stream_desc_128b_r_rgnt_subtractive ? subtractive_axi_rid : '0);

    assign stream_desc_128b_r.data = 
        (stream_desc_128b_r_rgnt_desc_ram ? desc_ram_axi_rdata : 128'b0) |
        (stream_desc_128b_r_rgnt_subtractive ? subtractive_axi_rdata : 128'b0);

    assign stream_desc_128b_r.resp = 
        (stream_desc_128b_r_rgnt_desc_ram ? desc_ram_axi_rresp : '0) |
        (stream_desc_128b_r_rgnt_subtractive ? subtractive_axi_rresp : '0);

    assign stream_desc_128b_r.last = 
        (stream_desc_128b_r_rgnt_desc_ram ? desc_ram_axi_rlast : '0) |
        (stream_desc_128b_r_rgnt_subtractive ? subtractive_axi_rlast : '0);

    assign stream_desc_128b_r.user = 
        (stream_desc_128b_r_rgnt_desc_ram ? desc_ram_axi_ruser : '0) |
        (stream_desc_128b_r_rgnt_subtractive ? subtractive_axi_ruser : '0);

    assign stream_desc_128b_rvalid = 
        (stream_desc_128b_r_rgnt_desc_ram ? desc_ram_axi_rvalid : '0) |
        (stream_desc_128b_r_rgnt_subtractive ? subtractive_axi_rvalid : '0);


    // Master: stream_rd, Width path: 128b
    assign stream_rd_128b_arready = 
        (stream_rd_128b_ar_gnt_ddr ? ddr_axi_arready : '0) |
        (stream_rd_128b_ar_gnt_lfsr_src ? lfsr_src_axi_arready : '0) |
        (stream_rd_128b_ar_gnt_subtractive ? subtractive_axi_arready : '0);

    assign stream_rd_128b_r.id = 
        (stream_rd_128b_r_rgnt_ddr ? ddr_axi_rid : '0) |
        (stream_rd_128b_r_rgnt_lfsr_src ? lfsr_src_axi_rid : '0) |
        (stream_rd_128b_r_rgnt_subtractive ? subtractive_axi_rid : '0);

    assign stream_rd_128b_r.data = 
        (stream_rd_128b_r_rgnt_ddr ? ddr_axi_rdata : 128'b0) |
        (stream_rd_128b_r_rgnt_lfsr_src ? lfsr_src_axi_rdata : 128'b0) |
        (stream_rd_128b_r_rgnt_subtractive ? subtractive_axi_rdata : 128'b0);

    assign stream_rd_128b_r.resp = 
        (stream_rd_128b_r_rgnt_ddr ? ddr_axi_rresp : '0) |
        (stream_rd_128b_r_rgnt_lfsr_src ? lfsr_src_axi_rresp : '0) |
        (stream_rd_128b_r_rgnt_subtractive ? subtractive_axi_rresp : '0);

    assign stream_rd_128b_r.last = 
        (stream_rd_128b_r_rgnt_ddr ? ddr_axi_rlast : '0) |
        (stream_rd_128b_r_rgnt_lfsr_src ? lfsr_src_axi_rlast : '0) |
        (stream_rd_128b_r_rgnt_subtractive ? subtractive_axi_rlast : '0);

    assign stream_rd_128b_r.user = 
        (stream_rd_128b_r_rgnt_ddr ? ddr_axi_ruser : '0) |
        (stream_rd_128b_r_rgnt_lfsr_src ? lfsr_src_axi_ruser : '0) |
        (stream_rd_128b_r_rgnt_subtractive ? subtractive_axi_ruser : '0);

    assign stream_rd_128b_rvalid = 
        (stream_rd_128b_r_rgnt_ddr ? ddr_axi_rvalid : '0) |
        (stream_rd_128b_r_rgnt_lfsr_src ? lfsr_src_axi_rvalid : '0) |
        (stream_rd_128b_r_rgnt_subtractive ? subtractive_axi_rvalid : '0);


    // Master: stream_wr, Width path: 128b
